schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/content-refresh-sop.json",
  "title": "Content Refresh SOP playbook step",
  "type": "object",
  "required": ["thresholds", "window", "urls", "decision_branches"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https://[^\\s/]+/"},
    "count": {"type": "integer", "minimum": 0},
    "gsc": {
      "type": "object",
      "required": ["clicks", "impressions", "avg_position"],
      "additionalProperties": false,
      "properties": {"clicks": {"$ref": "#/definitions/count"}, "impressions": {"$ref": "#/definitions/count"}, "avg_position": {"type": "number", "minimum": 1}}
    },
    "ga4": {
      "type": "object",
      "required": ["sessions", "key_events"],
      "additionalProperties": false,
      "properties": {"sessions": {"$ref": "#/definitions/count"}, "key_events": {"$ref": "#/definitions/count"}}
    },
    "rank": {
      "type": "object",
      "required": ["target_query", "position"],
      "additionalProperties": false,
      "properties": {"target_query": {"type": "string", "minLength": 3}, "position": {"type": "number", "minimum": 1}}
    },
    "baseline": {
      "type": "object",
      "required": ["published_at", "days", "clicks", "impressions", "avg_position", "sessions", "key_events"],
      "additionalProperties": false,
      "properties": {
        "published_at": {"$ref": "#/definitions/date"},
        "days": {"const": 28},
        "clicks": {"$ref": "#/definitions/count"},
        "impressions": {"$ref": "#/definitions/count"},
        "avg_position": {"type": "number", "minimum": 1},
        "sessions": {"$ref": "#/definitions/count"},
        "key_events": {"$ref": "#/definitions/count"}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "thresholds": {
      "type": "object",
      "required": ["impressions_trend_pct", "position_decay_positions", "intent_shift_query_mix_pct"],
      "additionalProperties": false,
      "properties": {
        "impressions_trend_pct": {"type": "number", "maximum": 0},
        "position_decay_positions": {"type": "number", "exclusiveMinimum": 0},
        "intent_shift_query_mix_pct": {"type": "number", "exclusiveMinimum": 0}
      }
    },
    "window": {
      "type": "object",
      "required": ["trailing_days", "prior_days", "span_months", "source"],
      "additionalProperties": false,
      "properties": {
        "trailing_days": {"type": "integer", "minimum": 28},
        "prior_days": {"type": "integer", "minimum": 28},
        "span_months": {"type": "integer", "minimum": 1},
        "source": {"type": "string", "enum": ["persisted_export", "search_console_ui"]}
      },
      "if": {"properties": {"span_months": {"minimum": 17}}},
      "then": {"properties": {"source": {"const": "persisted_export"}}}
    },
    "urls": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["url", "evergreen", "url_age_months", "dataset", "signals", "verdict"],
        "additionalProperties": false,
        "properties": {
          "url": {"$ref": "#/definitions/url"},
          "evergreen": {"const": true},
          "url_age_months": {"type": "integer", "minimum": 12},
          "dataset": {
            "type": "object",
            "required": ["trailing", "prior"],
            "additionalProperties": false,
            "properties": {
              "trailing": {"type": "object", "required": ["gsc", "ga4", "rank"], "additionalProperties": false, "properties": {"gsc": {"$ref": "#/definitions/gsc"}, "ga4": {"$ref": "#/definitions/ga4"}, "rank": {"$ref": "#/definitions/rank"}}},
              "prior": {"type": "object", "required": ["gsc", "ga4", "rank"], "additionalProperties": false, "properties": {"gsc": {"$ref": "#/definitions/gsc"}, "ga4": {"$ref": "#/definitions/ga4"}, "rank": {"$ref": "#/definitions/rank"}}}
            }
          },
          "signals": {
            "type": "object",
            "required": ["impressions_trend_pct", "position_decay_positions", "intent_shift", "intent_shift_note"],
            "additionalProperties": false,
            "properties": {
              "impressions_trend_pct": {"type": "number"},
              "position_decay_positions": {"type": "number"},
              "intent_shift": {"type": "boolean"},
              "intent_shift_note": {"type": "string", "minLength": 10}
            }
          },
          "verdict": {"type": "string", "enum": ["refresh", "consolidate", "kill", "leave"]},
          "refresh": {
            "type": "object",
            "required": ["url_unchanged", "substantive_change", "date_modified_updated", "title_changed_for_intent", "checklist", "baseline", "reevaluation_at"],
            "additionalProperties": false,
            "properties": {
              "url_unchanged": {"const": true},
              "substantive_change": {"type": "boolean"},
              "date_modified_updated": {"type": "boolean"},
              "title_changed_for_intent": {"type": "boolean"},
              "checklist": {
                "type": "array",
                "minItems": 9,
                "maxItems": 9,
                "items": {
                  "type": "object",
                  "required": ["step", "name", "exit_criterion", "done"],
                  "additionalProperties": false,
                  "properties": {
                    "step": {"type": "integer", "minimum": 1, "maximum": 9},
                    "name": {"type": "string", "minLength": 5},
                    "exit_criterion": {"type": "string", "minLength": 15},
                    "done": {"type": "boolean"},
                    "skipped_reason": {"type": "string", "minLength": 10}
                  },
                  "if": {"properties": {"done": {"const": false}}},
                  "then": {"required": ["skipped_reason"]}
                }
              },
              "baseline": {"$ref": "#/definitions/baseline"},
              "reevaluation_at": {"$ref": "#/definitions/date"}
            },
            "if": {"properties": {"date_modified_updated": {"const": true}}},
            "then": {"properties": {"substantive_change": {"const": true}}}
          },
          "consolidate": {
            "type": "object",
            "required": ["survivor_url", "merged_urls", "redirects", "internal_links_rewritten", "baseline", "reevaluation_at"],
            "additionalProperties": false,
            "properties": {
              "survivor_url": {"$ref": "#/definitions/url"},
              "merged_urls": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/url"}},
              "redirects": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "object",
                  "required": ["from", "to", "status"],
                  "additionalProperties": false,
                  "properties": {"from": {"$ref": "#/definitions/url"}, "to": {"$ref": "#/definitions/url"}, "status": {"type": "integer", "enum": [301, 308]}}
                }
              },
              "internal_links_rewritten": {"const": true},
              "baseline": {"$ref": "#/definitions/baseline"},
              "reevaluation_at": {"$ref": "#/definitions/date"}
            }
          },
          "kill": {
            "type": "object",
            "required": ["http_status", "removed_from_sitemap", "removed_from_navigation", "internal_links_dropped", "redirect_target"],
            "additionalProperties": false,
            "properties": {
              "http_status": {"type": "integer", "enum": [410, 404]},
              "removed_from_sitemap": {"const": true},
              "removed_from_navigation": {"const": true},
              "internal_links_dropped": {"const": true},
              "redirect_target": {"type": "null"}
            }
          },
          "leave": {
            "type": "object",
            "required": ["reason", "next_review_at"],
            "additionalProperties": false,
            "properties": {"reason": {"type": "string", "minLength": 15}, "next_review_at": {"$ref": "#/definitions/date"}}
          }
        },
        "allOf": [
          {"if": {"properties": {"verdict": {"const": "refresh"}}}, "then": {"required": ["refresh"]}},
          {"if": {"properties": {"verdict": {"const": "consolidate"}}}, "then": {"required": ["consolidate"]}},
          {"if": {"properties": {"verdict": {"const": "kill"}}}, "then": {"required": ["kill"]}},
          {"if": {"properties": {"verdict": {"const": "leave"}}}, "then": {"required": ["leave"]}}
        ]
      }
    },
    "decision_branches": {
      "type": "array",
      "minItems": 3,
      "allOf": [
        {"contains": {"properties": {"signal": {"const": "impressions_trend"}}}},
        {"contains": {"properties": {"signal": {"const": "top_position_decay"}}}},
        {"contains": {"properties": {"signal": {"const": "intent_shift"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["signal", "when", "then"],
        "additionalProperties": false,
        "properties": {
          "signal": {"type": "string", "enum": ["impressions_trend", "top_position_decay", "intent_shift"]},
          "when": {"type": "string", "minLength": 10, "pattern": "[0-9]"},
          "then": {"type": "string", "enum": ["refresh", "consolidate", "kill", "leave"]}
        }
      }
    }
  }
}

output-contract.example:
{
  "thresholds": {"impressions_trend_pct": -20, "position_decay_positions": 2, "intent_shift_query_mix_pct": 30},
  "window": {"trailing_days": 90, "prior_days": 90, "span_months": 6, "source": "persisted_export"},
  "urls": [
    {
      "url": "https://example.com/blog/content-refresh-checklist",
      "evergreen": true,
      "url_age_months": 19,
      "dataset": {
        "trailing": {"gsc": {"clicks": 1240, "impressions": 38400, "avg_position": 7.8}, "ga4": {"sessions": 1180, "key_events": 41}, "rank": {"target_query": "content refresh checklist", "position": 8}},
        "prior": {"gsc": {"clicks": 2010, "impressions": 56500, "avg_position": 4.7}, "ga4": {"sessions": 1950, "key_events": 77}, "rank": {"target_query": "content refresh checklist", "position": 5}}
      },
      "signals": {"impressions_trend_pct": -32.0, "position_decay_positions": 3.1, "intent_shift": false, "intent_shift_note": "top 10 still how-to guides; query mix change 9 percent, under the 30 percent threshold"},
      "verdict": "refresh",
      "refresh": {
        "url_unchanged": true,
        "substantive_change": true,
        "date_modified_updated": true,
        "title_changed_for_intent": false,
        "checklist": [
          {"step": 1, "name": "re-run query and intent research", "exit_criterion": "top 10 SERP captured for 'content refresh checklist' on 2026-04-28; intent still how-to", "done": true},
          {"step": 2, "name": "update facts, statistics, prices, dates", "exit_criterion": "11 statistics replaced with 2025-2026 sources, each linked and dated", "done": true},
          {"step": 3, "name": "rewrite title, meta description, intro", "exit_criterion": "intro rewritten to the current intent; meta description under 155 characters", "done": true},
          {"step": 4, "name": "add sections top-ranking pages cover", "exit_criterion": "sections added for AI Overview impact and Core Web Vitals; gap list from step 1 closed", "done": true},
          {"step": 5, "name": "refresh screenshots, media, examples", "exit_criterion": "6 screenshots retaken on the 2026 Search Console UI", "done": true},
          {"step": 6, "name": "update internal links in and out", "exit_criterion": "4 newer posts now link to the page; 3 dead outbound links replaced", "done": true},
          {"step": 7, "name": "fix technical issues on the URL", "exit_criterion": "2 broken links fixed, alt text on all images, structured data validates, LCP under 2.5 s", "done": true},
          {"step": 8, "name": "update dateModified and append changelog", "exit_criterion": "dateModified 2026-05-06; changelog entry lists steps 2, 4, 5, 6", "done": true},
          {"step": 9, "name": "request re-indexing and record baseline", "exit_criterion": "URL inspection re-index requested; 28-day baseline stored", "done": true}
        ],
        "baseline": {"published_at": "2026-05-06", "days": 28, "clicks": 380, "impressions": 11900, "avg_position": 7.9, "sessions": 360, "key_events": 12},
        "reevaluation_at": "2026-08-04"
      }
    },
    {
      "url": "https://example.com/blog/what-is-a-content-audit",
      "evergreen": true,
      "url_age_months": 31,
      "dataset": {
        "trailing": {"gsc": {"clicks": 860, "impressions": 21000, "avg_position": 3.2}, "ga4": {"sessions": 820, "key_events": 33}, "rank": {"target_query": "what is a content audit", "position": 3}},
        "prior": {"gsc": {"clicks": 910, "impressions": 22600, "avg_position": 3.0}, "ga4": {"sessions": 870, "key_events": 35}, "rank": {"target_query": "what is a content audit", "position": 3}}
      },
      "signals": {"impressions_trend_pct": -7.1, "position_decay_positions": 0.2, "intent_shift": false, "intent_shift_note": "query mix change 4 percent; SERP features unchanged"},
      "verdict": "leave",
      "leave": {"reason": "all three signals inside thresholds: -7.1 percent impressions, 0.2 positions, no intent shift", "next_review_at": "2026-11-04"}
    }
  ],
  "decision_branches": [
    {"signal": "intent_shift", "when": "query mix changed by more than 30 percent or the SERP turned to a different result type", "then": "kill"},
    {"signal": "impressions_trend", "when": "impressions down more than 20 percent period over period with no intent shift", "then": "refresh"},
    {"signal": "top_position_decay", "when": "average position worse by more than 2 positions with no intent shift", "then": "refresh"},
    {"signal": "impressions_trend", "when": "impressions within 20 percent and position within 2 positions", "then": "leave"}
  ]
}

