        "prior": {"gsc": {"clicks": 2010, "impressions": 56500, "avg_position": 4.7}, "ga4": {"sessions": 1950, "key_events": 77}, "rank": {"target_query": "content refresh checklist", "position": 5}}
      },
      "signals": {"impressions_trend_pct": -12.0, "position_decay_positions": 1.0, "intent_shift": false, "intent_shift_note": "not checked this cycle"},
